package ug.audiocity.studio;
import java.io.*;import java.nio.file.*;import java.util.*;
public final class DrumRackBehaviorTests {
 static int n;static void ok(boolean b,String why){n++;if(!b)throw new AssertionError(why);}static void clean(File f){if(f.isDirectory())for(File c:f.listFiles())clean(c);f.delete();}
 public static void main(String[] args)throws Exception{
  DrumStepPress press=new DrumStepPress();press.down(0);int barAtRelease=1;BeatPilotDrumPattern p=new BeatPilotDrumPattern(100,2);p.set(press.consume(barAtRelease),0,15,106);ok(p.get(0,0,15)==106&&p.get(1,0,15)==0,"tap stays in bar held at touch-down when playback crosses bar end");press.down(1);p.set(press.consume(0),1,2,87);ok(p.get(1,1,2)==87&&p.get(0,1,2)==0,"long press remains in its touched bar across loop wrap");press.down(1);press.cancel();ok(press.consume(0)==0,"scroll cancellation discards the old touch target");ok(press.consume(1)==1,"accessibility click uses the displayed bar without a touch event");
  p.setSampleChoice(0,0);BeatPilotDrumPattern extended=p.resizedEmpty(8);for(int bar=2;bar<8;bar++)for(int lane=0;lane<8;lane++)for(int step=0;step<16;step++)ok(extended.get(bar,lane,step)==0,"manual added bars are empty");ok(extended.get(0,0,15)==106&&extended.get(1,1,2)==87&&extended.sampleChoice(0)==0,"growing preserves existing bars, velocity and chosen sample");ok(p.discardsNotes(1)&&!p.discardsNotes(2)&&!p.discardsNotes(4),"only shrinking occupied bars needs a warning");BeatPilotDrumPattern repeated=extended.repeatedBar(1);ok(repeated.get(0,1,2)==87&&repeated.get(7,1,2)==87&&repeated.get(0,0,15)==0,"explicit repeat copies only the selected bar");ok(repeated.sampleChoice(0)==0&&extended.get(0,0,15)==106,"explicit repeat preserves sample identity and its original draft");
  File dir=Files.createTempDirectory("acs-rack-behavior-").toFile();try{Core.Session s=new Core.Session();s.directory=dir.getAbsolutePath();s.bpm=240;BeatPilotDrumPattern beat=new BeatPilotDrumPattern(240,1);beat.set(0,0,0,110);PatternLibrary.Entry e=PatternLibrary.add(s,"Manual",beat);float[][] kit=new float[8][];for(int lane=0;lane<8;lane++){kit[lane]=new float[100];Arrays.fill(kit[lane],.1f);}PatternArrangement.place(s,e.id,kit,0,1);int files=dir.list().length;try{PatternArrangement.place(s,e.id,kit,0,2);throw new AssertionError("duplicate pattern stacked");}catch(IllegalArgumentException expected){n++;}ok(dir.list().length==files&&s.tracks.get(0).clips.size()==1,"duplicate placement is rejected before writing files or partly adding repeats");long bar=Core.beat(240)*4;PatternArrangement.place(s,e.id,kit,bar,1);ok(s.tracks.size()==1&&s.tracks.get(0).clips.size()==2,"placement at a free bar still works on independent drum tracks");}finally{clean(dir);}
  System.out.println("DrumRackBehaviorTests passed "+n+" checks");
 }
}
